CREATE OR REPLACE FUNCTION public.award_course_points(p_enrollment_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_enrollment RECORD;
    v_course RECORD;
    v_student_pts INTEGER;
    v_author_base_pts INTEGER;
    v_multiplier NUMERIC(4, 2);
    v_author_pts INTEGER;
    v_rows_updated INTEGER;
    v_has_passed BOOLEAN;
    v_student_rule_code TEXT;
BEGIN
    SELECT id, user_id, course_id, points_awarded INTO v_enrollment FROM course_enrollments WHERE id = p_enrollment_id;
    IF NOT FOUND THEN RETURN 'enrollment_not_found'; END IF;
    IF v_enrollment.points_awarded THEN RETURN 'already_awarded'; END IF;

    SELECT EXISTS (SELECT 1 FROM course_quiz_attempts WHERE enrollment_id = p_enrollment_id AND passed = true) INTO v_has_passed;
    IF NOT v_has_passed THEN RETURN 'not_passed'; END IF;

    SELECT id, author_id, title, slug, course_type, COALESCE(avg_rating, 0) AS avg_rating
    INTO v_course
    FROM courses WHERE id = v_enrollment.course_id;

    UPDATE course_enrollments SET points_awarded = TRUE, completed_at = COALESCE(completed_at, NOW())
        WHERE id = p_enrollment_id AND points_awarded = FALSE;
    GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
    IF v_rows_updated = 0 THEN RETURN 'race'; END IF;

    -- Self-study (consultant authoring own course) earns nothing
    IF v_course.course_type = 'consultant' AND v_course.author_id = v_enrollment.user_id THEN
        RETURN 'self_study_no_points';
    END IF;

    -- Pick student rule code by course_type
    v_student_rule_code := CASE
        WHEN v_course.course_type = 'company' THEN 'course_completed_company_student'
        ELSE 'course_completed_student'
    END;

    SELECT points INTO v_student_pts FROM loyalty_rules WHERE code = v_student_rule_code AND is_active = TRUE;
    IF v_student_pts IS NOT NULL THEN
        INSERT INTO loyalty_transactions (user_id, points, source_type, source_id, description)
        VALUES (
            v_enrollment.user_id,
            v_student_pts,
            v_student_rule_code,
            v_course.id,
            'Ukończenie szkolenia: ' || v_course.title
        );
    END IF;

    -- Author bonus only for consultant-authored courses (company courses authored by admin/trainer earn nothing)
    IF v_course.course_type = 'consultant' AND v_course.author_id IS NOT NULL THEN
        SELECT points INTO v_author_base_pts FROM loyalty_rules WHERE code = 'course_completed_author_reward' AND is_active = TRUE;
        v_multiplier := 1.0 + LEAST(0.2, GREATEST(0, v_course.avg_rating) / 5.0 * 0.2);
        v_author_pts := ROUND(COALESCE(v_author_base_pts, 50) * v_multiplier);

        INSERT INTO loyalty_transactions (user_id, points, source_type, source_id, description)
        VALUES (
            v_course.author_id,
            v_author_pts,
            'course_completed_author_reward',
            v_course.id,
            'Uczeń ukończył Twoje szkolenie: ' || v_course.title || ' (×' || TO_CHAR(v_multiplier, 'FM9.00') || ')'
        );

        PERFORM create_notification(
            v_course.author_id, 'course_completed',
            'Ktoś ukończył Twoje szkolenie!', 'Someone completed your course!',
            '+' || v_author_pts || ' pkt — ' || v_course.title,
            '+' || v_author_pts || ' pts — ' || v_course.title,
            '/akademia/' || v_course.slug, 'normal'
        );
    END IF;

    RETURN 'awarded';
END;
$function$

CREATE OR REPLACE FUNCTION public.award_first_publish_bonus(p_course_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_author_id UUID; v_title TEXT; v_slug TEXT; v_count INTEGER; v_bonus_pts INTEGER;
BEGIN
    SELECT author_id, title, slug INTO v_author_id, v_title, v_slug FROM courses WHERE id = p_course_id;
    IF NOT FOUND THEN RETURN 'course_not_found'; END IF;
    SELECT COUNT(*) INTO v_count FROM courses WHERE author_id = v_author_id AND status = 'published' AND id <> p_course_id;
    IF v_count > 0 THEN RETURN 'not_first'; END IF;
    SELECT points INTO v_bonus_pts FROM loyalty_rules WHERE code = 'course_first_publish_bonus' AND is_active = TRUE;
    IF v_bonus_pts IS NULL THEN RETURN 'rule_inactive'; END IF;
    INSERT INTO loyalty_transactions (user_id, points, source_type, source_id, description)
    VALUES (v_author_id, v_bonus_pts, 'course_first_publish_bonus', p_course_id, 'Bonus za pierwsze opublikowane szkolenie: ' || v_title);
    PERFORM create_notification(
        v_author_id, 'course_approved',
        'Bonus za pierwsze szkolenie!', 'First-course publication bonus!',
        '+' || v_bonus_pts || ' pkt — ' || v_title,
        '+' || v_bonus_pts || ' pts — ' || v_title,
        '/akademia/' || v_slug, 'normal'
    );
    RETURN 'awarded';
END;
$function$

CREATE OR REPLACE FUNCTION public.block_employment_reversal_after_exit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.employment_status = 'offboarding'
       AND NEW.employment_status NOT IN ('offboarding', 'exited') THEN
        IF EXISTS (
            SELECT 1 FROM exit_interviews
            WHERE user_id = NEW.id
              AND status IN ('submitted', 'reviewed', 'archived')
        ) THEN
            RAISE EXCEPTION 'Nie można cofnąć statusu offboarding — istnieje wypełniony exit interview. Skontaktuj się z TCM.'
                USING ERRCODE = 'P0001';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.pin_profile_privilege_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
    IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
        -- Ślad TYLKO gdy ktoś realnie ruszył kolumnę uprawnień — inaczej każda
        -- zmiana avatara zaśmiecałaby dziennik. Bez tego wpisu cofnięcie jest
        -- całkowicie ciche: atakujący dostaje 200 z niezmienionym wierszem.
        IF NEW.role IS DISTINCT FROM OLD.role
            OR NEW.manager_id IS DISTINCT FROM OLD.manager_id
            OR NEW.employment_status IS DISTINCT FROM OLD.employment_status
            OR NEW.is_inbox_handler IS DISTINCT FROM OLD.is_inbox_handler
            OR NEW.has_tcm_access IS DISTINCT FROM OLD.has_tcm_access
            OR NEW.can_log_overtime IS DISTINCT FROM OLD.can_log_overtime
            OR NEW.can_view_tech_map IS DISTINCT FROM OLD.can_view_tech_map
            OR NEW.can_view_legal_monitor IS DISTINCT FROM OLD.can_view_legal_monitor
            OR NEW.leave_entitlement_days IS DISTINCT FROM OLD.leave_entitlement_days
            OR NEW.termination_date IS DISTINCT FROM OLD.termination_date
            OR NEW.leave_carried_over_days IS DISTINCT FROM OLD.leave_carried_over_days
            OR NEW.leave_used_initial_days IS DISTINCT FROM OLD.leave_used_initial_days
            OR NEW.hired_at IS DISTINCT FROM OLD.hired_at
            OR NEW.is_external IS DISTINCT FROM OLD.is_external
        THEN
            INSERT INTO public.audit_logs (user_id, action, details, ip_address)
            VALUES (
                auth.uid(),
                'PROFILE_PRIVILEGE_CHANGE_BLOCKED',
                jsonb_build_object(
                    'target_user_id', NEW.id,
                    'attempted_role', NEW.role,
                    'current_role', OLD.role,
                    'attempted_employment_status', NEW.employment_status
                ),
                'trigger'
            );
        END IF;

        NEW.role                    := OLD.role;
        NEW.manager_id              := OLD.manager_id;
        NEW.employment_status       := OLD.employment_status;
        NEW.is_inbox_handler        := OLD.is_inbox_handler;
        NEW.has_tcm_access          := OLD.has_tcm_access;
        NEW.can_log_overtime        := OLD.can_log_overtime;
        NEW.can_view_tech_map       := OLD.can_view_tech_map;
        NEW.can_view_legal_monitor  := OLD.can_view_legal_monitor;
        NEW.leave_entitlement_days  := OLD.leave_entitlement_days;
        NEW.leave_carried_over_days := OLD.leave_carried_over_days;
        NEW.leave_used_initial_days := OLD.leave_used_initial_days;
        NEW.hired_at                := OLD.hired_at;
        NEW.termination_date        := OLD.termination_date;
        NEW.is_external             := OLD.is_external;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_quiz_attempt(p_course_id uuid, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_enrollment RECORD;
    v_total_questions INTEGER; v_correct_count INTEGER := 0;
    v_score_percent INTEGER; v_passed BOOLEAN;
    v_attempt_id UUID; v_award_status TEXT := NULL;
BEGIN
    IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
    SELECT id, points_awarded INTO v_enrollment FROM course_enrollments WHERE course_id = p_course_id AND user_id = v_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'not_enrolled'; END IF;
    SELECT COUNT(*) INTO v_total_questions FROM course_quiz_questions WHERE course_id = p_course_id;
    IF v_total_questions = 0 THEN RAISE EXCEPTION 'no_quiz_questions'; END IF;
    SELECT COUNT(*) INTO v_correct_count
    FROM jsonb_array_elements(p_answers) AS a
    JOIN course_quiz_options o ON o.id = (a->>'selected_option_id')::UUID
    JOIN course_quiz_questions q ON q.id = o.question_id AND q.id = (a->>'question_id')::UUID
    WHERE q.course_id = p_course_id AND o.is_correct = TRUE;
    v_score_percent := ROUND((v_correct_count::NUMERIC / v_total_questions) * 100);
    v_passed := v_score_percent >= 70;
    INSERT INTO course_quiz_attempts (enrollment_id, user_id, course_id, answers, score_percent, passed)
    VALUES (v_enrollment.id, v_user_id, p_course_id, p_answers, v_score_percent, v_passed)
    RETURNING id INTO v_attempt_id;
    IF v_passed AND NOT v_enrollment.points_awarded THEN
        v_award_status := award_course_points(v_enrollment.id);
    END IF;
    RETURN jsonb_build_object(
        'score_percent', v_score_percent,
        'passed', v_passed,
        'attempt_id', v_attempt_id,
        'already_awarded', v_enrollment.points_awarded,
        'award_status', v_award_status
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_course_answers_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE course_questions SET answers_count = answers_count + 1 WHERE id = NEW.question_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE course_questions SET answers_count = GREATEST(0, answers_count - 1) WHERE id = OLD.question_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_course_qa_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_learning_paths_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_lp_enrollment_stats()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE learning_paths SET enrollments_count = enrollments_count + 1 WHERE id = NEW.path_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE learning_paths SET enrollments_count = GREATEST(0, enrollments_count - 1) WHERE id = OLD.path_id;
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.completed_at IS NULL AND NEW.completed_at IS NOT NULL THEN
            UPDATE learning_paths SET completions_count = completions_count + 1 WHERE id = NEW.path_id;
        ELSIF OLD.completed_at IS NOT NULL AND NEW.completed_at IS NULL THEN
            UPDATE learning_paths SET completions_count = GREATEST(0, completions_count - 1) WHERE id = NEW.path_id;
        END IF;
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_course_enrollment_stats()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE courses SET enrollments_count = enrollments_count + 1, updated_at = NOW() WHERE id = NEW.course_id;
    ELSIF TG_OP = 'UPDATE' AND OLD.completed_at IS NULL AND NEW.completed_at IS NOT NULL THEN
        UPDATE courses SET completions_count = completions_count + 1, updated_at = NOW() WHERE id = NEW.course_id;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_course_ratings_stats()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_course_id UUID; v_avg NUMERIC(3, 2); v_count INTEGER;
BEGIN
    v_course_id := COALESCE(NEW.course_id, OLD.course_id);
    SELECT COALESCE(AVG(rating)::NUMERIC(3, 2), 0), COUNT(*) INTO v_avg, v_count FROM course_ratings WHERE course_id = v_course_id;
    UPDATE courses SET avg_rating = v_avg, ratings_count = v_count, updated_at = NOW() WHERE id = v_course_id;
    RETURN COALESCE(NEW, OLD);
END;
$function$

